mapper.select:
SELECT
analysis_id,
course_id,
rev_no,
dem_id,
sample_itv_m,
status_cd
FROM terrain_analysis
WHERE course_id = #{courseId}
AND rev_no = #{revNo}
AND dem_id = #{demId}
AND sample_itv_m = #{sampleIntervalM}

SELECT a.analysis_id, a.course_id, a.rev_no, a.dem_id, a.sample_itv_m, a.status_cd
FROM terrain_analysis a
JOIN course c ON c.course_id = a.course_id AND c.rev_no = a.rev_no
WHERE c.course_id = #{courseId}
AND c.owner_user_id = #{ownerUserId}
AND c.del_yn = 'N'
AND a.dem_id = #{demId}
AND a.sample_itv_m = #{sampleIntervalM}

SELECT a.analysis_id, a.course_id, a.rev_no, a.dem_id, a.sample_itv_m, a.status_cd
FROM terrain_analysis a
JOIN course c ON c.course_id = a.course_id
WHERE a.analysis_id = #{analysisId}
AND c.owner_user_id = #{ownerUserId}
AND c.del_yn = 'N'

mapper.delete:
DELETE FROM elevation_sample
WHERE analysis_id = #{analysisId}
AND EXISTS (
SELECT 1 FROM terrain_analysis
WHERE analysis_id = #{analysisId}
AND status_cd = 'FAILED'
)
